import { VaultList } from '@/apis/path'
import useVaultsFarmingStore from '@/store/vaults-farming'
import useVaultsListV2Store from '@/store/vaults-v2/useVaultsList'
import { useFetch } from '@cetus/hooks'
import { useGetToken } from '@cetus/hooks/src/useToken'
import useTokenPrice from '@cetus/hooks/src/useTokenPrice'
import { useAccountStore } from '@cetus/stores'
import usePeripherySDKStore from '@cetus/stores/src/usePeripherySDKStore'
import { d } from '@cetusprotocol/common-sdk'
import { buildVaultsBalance } from 'haedal-vault-sdk'
import useGetVaultPoolList from '../vault-v2/useGetVaultPoolList'

export default function useGetVaultsFarmingList() {
  const { fetchByApi } = useFetch()
  const { volatileVaultsSdk, haedalFarmSdk } = usePeripherySDKStore()
  const { currentAccount } = useAccountStore()
  const { setVaultsFarmsRewardObj } = useVaultsListV2Store()
  const { getTokenInfo } = useGetToken()
  const { fetchTokenPrices } = useTokenPrice()
  const { setVaultsFarmingObj } = useVaultsFarmingStore()
  const { getLocalVaultPoolList } = useGetVaultPoolList()

  // 1. 拉取 Haedal Farming 原始数据
  const getHaedalFarmingApiData = async () => {
    try {
      const res = await (await fetch('https://www.haedal.xyz/api/v1/farming/pools')).json()
      if (res && res.code === 200) return res.data || []
      return []
    } catch (error) {
      return await haedalFarmSdk.Farms.getFarmsList()
    }
  }

  // 2. 拉取 Vaults List 并转为对象
  const getVaultsApiData = async () => {
    try {
      const vaultsRes = await fetchByApi(VaultList, 'GET')
      return vaultsRes.list.reduce((acc: any, curr: any) => {
        acc[curr.id] = curr
        return acc
      }, {})
    } catch (error) {
      const { vaultListObj } = await getLocalVaultPoolList()
      return vaultListObj
    }
  }

  // 3. 计算 Farming 详情
  const processFarmingData = async (list: any[], vaultsObj: Record<string, any>) => {
    console.log('🚀🚀🚀 ~ useGetVaultsFarmingContractInfo.ts:50 ~ processFarmingData ~ list:', list)
    const rewardCoinList: string[] = []
    const vaultsFarmsRewardObj: Record<string, any> = {}
    const vaultsFarmingObj: Record<string, any> = {}

    for (const item of list) {
      console.log('🚀🚀🚀 ~ useGetVaultsFarmingContractInfo.ts:57 ~ processFarmingData ~ item:', item)
      const { rewardConfigs, poolId, coinDetail, vaultPool } = item
      console.log('🚀🚀🚀 ~ useGetVaultsFarmingContractInfo.ts:58 ~ processFarmingData ~ rewardConfigs:', rewardConfigs)
      const currentVaultApiInfo = vaultsObj[vaultPool.id]
      console.log('🚀🚀🚀 ~ useGetVaultsFarmingContractInfo.ts:58 ~ processFarmingData ~ currentVaultApiInfo:', currentVaultApiInfo)
      if (!currentVaultApiInfo) continue

      const { clmm_pool, clmmPoolAddress } = currentVaultApiInfo
      const vaultId = currentVaultApiInfo?.id || currentVaultApiInfo?.vaultId
      const coinTypeA = currentVaultApiInfo?.coin_type_a || currentVaultApiInfo?.coinTypeA
      const coinTypeB = currentVaultApiInfo?.coin_type_b || currentVaultApiInfo?.coinTypeB

      console.log('🚀🚀🚀 ~ useGetVaultsFarmingContractInfo.ts:61 ~ processFarmingData ~ clmm_pool:', clmm_pool)

      rewardCoinList.push(coinTypeA, coinTypeB)

      const clmmContractInfo = await volatileVaultsSdk?.CetusClmmSDK?.Pool.getPool(clmm_pool || clmmPoolAddress)
      const vaultContractInfo = await volatileVaultsSdk.Vaults.getPool(vaultId)
      const positionInfo = buildVaultsBalance(currentAccount?.address || '', item.balance, vaultContractInfo, clmmContractInfo)

      const tokenA = await getTokenInfo(coinTypeA)
      const tokenB = await getTokenInfo(coinTypeB)

      const farmingPoolAmountA = d(positionInfo.amount_a)
        .div(10 ** tokenA?.decimals)
        .toString()
      const farmingPoolAmountB = d(positionInfo.amount_b)
        .div(10 ** tokenB?.decimals)
        .toString()

      vaultsFarmingObj[vaultId] = { ...item, isVaultsFarming: true }

      for (const rewardItem of rewardConfigs) {
        const rewardRate = d(rewardItem?.rate || 0)
        if (rewardRate.lte(0)) continue

        const rewardDecimals = rewardItem?.coinDetail?.decimals
        const rewardItemRate = rewardRate
          .mul(60 * 60 * 24)
          .div(10 ** rewardDecimals)
          .toString()

        if (!vaultsFarmsRewardObj[vaultId]) {
          vaultsFarmsRewardObj[vaultId] = {
            rewardList: [],
            farmingPoolAmountA,
            farmingPoolAmountB,
            coinTypeA,
            coinTypeB,
            poolId,
            coinDetail
          }
        }

        vaultsFarmsRewardObj[vaultId].rewardList.push({
          rewardItemRate,
          ...item.coinDetail,
          rewardCoinType: rewardItem.rewardCoinType
        })
        console.log('🚀🚀🚀 ~ useGetVaultsFarmingContractInfo.ts:112 ~ processFarmingData ~ rewardItem:', rewardItem.rewardCoinType)

        console.log('🚀🚀🚀 ~ useGetVaultsFarmingContractInfo.ts:114 ~ processFarmingData ~ rewardCoinList:', rewardCoinList)
        rewardCoinList.push(rewardItem.rewardCoinType)
      }
    }

    console.log('🚀🚀🚀 ~ useGetVaultsFarmingContractInfo.ts:119 ~ processFarmingData ~ rewardCoinList:', rewardCoinList)
    return { vaultsFarmingObj, vaultsFarmsRewardObj, rewardCoinList: [...new Set(rewardCoinList)] }
  }

  // 4. 主入口
  const getHaedalFarmingList = async () => {
    const haedalList = await getHaedalFarmingApiData()
    const vaultsObj = await getVaultsApiData()

    const { vaultsFarmingObj, vaultsFarmsRewardObj, rewardCoinList } = await processFarmingData(haedalList, vaultsObj)

    setVaultsFarmingObj(vaultsFarmingObj)
    setVaultsFarmsRewardObj(vaultsFarmsRewardObj)
    fetchTokenPrices(rewardCoinList)
  }

  return { getHaedalFarm: getHaedalFarmingList, getHaedalFarmingList }
}
