import { CetusTooltip } from '@cetus/design'
import { HTextLabelBox } from '@cetus/ui-kit'
import { Box, HStack, StackProps, Text, TextProps, VStack } from '@chakra-ui/react'
import { useState } from 'react'

interface VaultsAprBlockProps {
  vaultsLstApyDisplay: string
  vaultsApyDisplay: string
  vaultsTotalApyDisplay: string
  vaultsAprDisplay: string
  vaultFarmingAprDisplay?: string
  category?: string
  wrapStyle?: StackProps
  isVaultsFarming?: boolean
  farmingTextStyle?: TextProps
}

function VaultsAprBlock({
  vaultsLstApyDisplay,
  vaultsApyDisplay,
  vaultsTotalApyDisplay,
  category,
  vaultsAprDisplay,
  wrapStyle,
  isVaultsFarming,
  vaultFarmingAprDisplay,
  farmingTextStyle = {}
}: VaultsAprBlockProps) {
  return (
    <CetusTooltip
      tooltip={
        category == 'cetus' ? (
          <VaultsAprTooltipContentLST
            vaultsApyDisplay={vaultsApyDisplay}
            vaultsLstApyDisplay={vaultsLstApyDisplay}
            vaultsTotalApyDisplay={vaultsTotalApyDisplay}
            vaultsAprDisplay={vaultsAprDisplay}
            category={category}
          />
        ) : (
          <VaultsAprTooltipContent
            vaultsApyDisplay={vaultsApyDisplay}
            vaultsLstApyDisplay={vaultsLstApyDisplay}
            vaultsTotalApyDisplay={vaultsTotalApyDisplay}
            vaultsAprDisplay={vaultsAprDisplay}
            category={category}
            vaultFarmingAprDisplay={vaultFarmingAprDisplay}
            isVaultsFarming={isVaultsFarming}
          />
        )
      }
      placement="bottom"
      // maxW="260px"
    >
      <VStack
        gap={{
          base: '4px',
          lg: '2px'
        }}
        alignItems={{
          base: 'flex-end',
          lg: 'center'
        }}
        {...wrapStyle}
      >
        <Text textColor="text_caption" textAlign="right" fontWeight="500" textDecoration="underline dotted" color="primary">
          {category == 'cetus' ? vaultsTotalApyDisplay : vaultsApyDisplay}
        </Text>
        {isVaultsFarming && vaultFarmingAprDisplay && (
          <Text
            bg="primary_yellow_opacity.10"
            color="primary_yellow"
            borderRadius="4px"
            fontSize="12px"
            p={{
              base: '4px 6px',
              lg: '0 4px'
            }}
            {...farmingTextStyle}
          >
            +{vaultFarmingAprDisplay}
          </Text>
        )}
      </VStack>
    </CetusTooltip>
  )
}

export const VaultsAprTooltipContentLST = ({
  vaultsLstApyDisplay,
  vaultsApyDisplay,
  vaultsTotalApyDisplay,
  category,
  vaultsAprDisplay
}: VaultsAprBlockProps) => {
  return (
    <VStack gap="12px" w="100%" pt="8px">
      <VStack>
        <HTextLabelBox
          label="Total APY"
          labelStyle={{
            fontSize: '14px'
          }}
          valueStyle={{
            fontSize: '14px'
          }}
          wrapStyle={{
            gap: '16px'
          }}
          value={vaultsTotalApyDisplay}
        />
        <HStack h="1px" w="100%" backgroundColor="border" />
        <HTextLabelBox
          label="Fees and Rewards"
          labelStyle={{
            fontSize: '12px'
          }}
          valueStyle={{
            fontSize: '12px'
          }}
          wrapStyle={{
            gap: '16px'
          }}
          value={vaultsApyDisplay}
        />
        <HTextLabelBox
          label="LST"
          labelStyle={{
            fontSize: '12px'
          }}
          wrapStyle={{
            gap: '16px'
          }}
          value={vaultsLstApyDisplay}
          valueStyle={{
            fontSize: '12px'
          }}
        />
      </VStack>
    </VStack>
  )
}

