import { create, StateCreator } from 'zustand'

type CurrentVaultFarm = {
  vaultsFarmingStakeLoading: boolean
  setVaultsFarmingStakeLoading: (status: boolean) => void

  vaultsFarmingStaked: any
  setVaultsFarmingStaked: (data: any) => void

  vaultsFarmingAvailableRewardsLoading: boolean
  setVaultsFarmingAvailableRewardsLoading: (status: boolean) => void

  vaultsFarmingAvailableRewards: any
  setVaultsFarmingAvailableRewards: (reward: any) => void

  vaultsFarmingObj: any
  setVaultsFarmingObj: (data: any) => void

  autoClaimFarmingReward: boolean
  setAutoCliamFarmingReward: (status: boolean) => void

  clearVaultsFarmingInfo: () => void

  autoClaimStakeFarming: boolean
  setAutoClaimStakeFarming: (status: boolean) => void
}

const store: StateCreator<CurrentVaultFarm> = (set, get) => ({
  vaultsFarmingStaked: {},
  setVaultsFarmingStaked: (data: any) => {
    const prev = get().vaultsFarmingStaked || {}
    const merged = { ...prev, ...data }
    set({ vaultsFarmingStaked: merged })
  },
  vaultsFarmingStakeLoading: false,
  setVaultsFarmingStakeLoading: (status: boolean) => set({ vaultsFarmingStakeLoading: status }),

  vaultsFarmingAvailableRewards: {},
  setVaultsFarmingAvailableRewards: (data: any) => {
    const prev = get().vaultsFarmingAvailableRewards || {}
    const merged = { ...prev, ...data }
    set({ vaultsFarmingAvailableRewards: merged })
  },

  vaultsFarmingAvailableRewardsLoading: false,
  setVaultsFarmingAvailableRewardsLoading: (status: boolean) => set({ vaultsFarmingAvailableRewardsLoading: status }),

  vaultsFarmingObj: {},
  setVaultsFarmingObj: (data: any) => set({ vaultsFarmingObj: data }),

  autoClaimFarmingReward: true,
  setAutoCliamFarmingReward: (status: boolean) => set({ autoClaimFarmingReward: status }),

  autoClaimStakeFarming: true,
  setAutoClaimStakeFarming: (status: boolean) => set({ autoClaimStakeFarming: status }),

  clearVaultsFarmingInfo: () => set({ vaultsFarmingStaked: {}, vaultsFarmingAvailableRewards: {} })
})

const useVaultsFarmingStore = create(store)

export default useVaultsFarmingStore
