import useVaultsFarmingStore from '@/store/vaults-farming'
import { useAccountStore } from '@cetus/stores'
import usePeripherySDKStore from '@cetus/stores/src/usePeripherySDKStore'
import { Decimal, formatNumber } from '@cetus/utils'
import { d } from '@cetusprotocol/common-sdk'
import { StakedOptions } from 'haedal-farm-sdk'
import { useEffect, useRef } from 'react'
import useGetVaultFarmingAvailableRewards from './useGetVaultFarmingAvailableRewards'

export default function useGetVaultFarmingStaked() {
  const { haedalFarmSdk } = usePeripherySDKStore()

  const { setVaultsFarmingStakeLoading, setVaultsFarmingStaked, vaultsFarmingObj, setVaultsFarmingAvailableRewardsLoading } = useVaultsFarmingStore()
  const { getVaultFarmingAvailableRewards } = useGetVaultFarmingAvailableRewards()
  const { currentAccount } = useAccountStore()

  const currentAcc = useRef(currentAccount?.address)
  useEffect(() => {
    currentAcc.current = currentAccount?.address
  }, [currentAccount?.address])

  const getVaultsFarmingStaked = async (params: StakedOptions, vaultsFarmingInfo?: any, isRefresh?: boolean) => {
    console.log('🚀🚀🚀 ~ useGetVaultFarmingStaked.ts:13 ~ getVaultsFarmingStaked ~ vaultsFaringInfo:', vaultsFarmingInfo)
    setVaultsFarmingStakeLoading(true)
    setVaultsFarmingAvailableRewardsLoading(true)
    try {
      console.log('🚀🚀🚀 ~ useGetVaultFarmingStaked.ts:20 ~ getVaultsFarmingStaked ~ params:', params)
      const result = await haedalFarmSdk.Farms.getFarmDeposit(params)
      console.log('🚀🚀🚀 ~ useGetVaultFarmingStaked.ts:17 ~ getVaultsFarmingStaked ~ result:', result)
      const formatted = formatVaultsFarmingStaked(
        {
          ...params,
          ...result
        },
        vaultsFarmingInfo
      )
      console.log('🚀🚀🚀 ~ useGetVaultFarmingStaked.ts:25 ~ getVaultsFarmingStaked ~ formatted:', formatted)
      if (currentAccount?.address == currentAcc.current) {
        setVaultsFarmingStaked({
          [vaultsFarmingInfo?.vaultPool.id]: formatted
        })
        getVaultFarmingAvailableRewards(
          {
            stakeCoinType: formatted.stakeCoinType,
            poolId: formatted.poolId,
            stakeObjectId: formatted.stakeObjectId
          },
          vaultsFarmingInfo?.vaultPool.id
        )
        return formatted
      } else {
        setVaultsFarmingStakeLoading(false)
        setVaultsFarmingAvailableRewardsLoading(false)
      }
    } catch (error) {
      console.error('[VaultFarming] Failed to fetch staked info:', error)
      setVaultsFarmingStaked(undefined)
    }
  }

  const formatVaultsFarmingStaked = (data: any, vaultsFaringInfo: any) => {
    let pool
    if (!vaultsFaringInfo) {
      pool = vaultsFarmingObj?.[data.poolId]
      if (!pool) {
        console.warn(`[VaultFarming] Missing vaultsFarmingObj for pool ${data.poolId}`)
        return undefined
      }
    } else {
      pool = vaultsFaringInfo
    }
    console.log('🚀🚀🚀 ~ useGetVaultFarmingStaked.ts:42 ~ formatVaultsFarmingStaked ~ pool:', pool)

    const { coinDetail, rewardConfigs } = pool

    const stakedBalanceFormat = d(data.stakedBalance)
      .div(10 ** (coinDetail?.decimals ?? 0))
      .toString()

    return {
      poolId: data.poolId,
      stakeObjectId: data.stakeObjectId,
      stakedBalance: data.stakedBalance,
      stakedBalanceFormat,
      stakedBalanceDisplay: formatNumber(stakedBalanceFormat, undefined, undefined, Decimal.ROUND_DOWN).toString(),
      coinDetail,
      stakeCoinType: data.stakeCoinType,
      rewardConfigs: (rewardConfigs ?? []).filter(ele => d(ele.rate).gt(0))
    }
  }

  return { getVaultsFarmingStaked }
}
