import useVaultsFarmingStore from '@/store/vaults-farming'
import usePeripherySDKStore from '@cetus/stores/src/usePeripherySDKStore'
import { d } from '@cetusprotocol/common-sdk'
import { RewardOptions } from 'haedal-farm-sdk'

export default function useGetVaultFarmingAvailableRewards() {
  const { haedalFarmSdk } = usePeripherySDKStore()
  const { setVaultsFarmingAvailableRewardsLoading, setVaultsFarmingAvailableRewards, vaultsFarmingObj } = useVaultsFarmingStore()

  const getVaultFarmingAvailableRewards = async (params: RewardOptions, vaultId: string) => {
    console.log('🚀🚀🚀 ~ useGetVaultFarmingAvailableRewards.ts:11 ~ getVaultFarmingAvailableRewards ~ params:', params)
    try {
      const result = await haedalFarmSdk.Farms.getAvailableRewards(params)
      console.log('🚀🚀🚀 ~ useGetVaultFarmingAvailableRewards.ts:15 ~ getVaultFarmingAvailableRewards ~ result:', result)

      const formatted = formatRewards(vaultId, result)
      setVaultsFarmingAvailableRewards({
        [vaultId]: formatted
      })

      console.log('[VaultFarming] Available rewards:', formatted)
      setVaultsFarmingAvailableRewardsLoading(false)
    } catch (error) {
      console.error('[VaultFarming] Error fetching rewards:', error)
      setVaultsFarmingAvailableRewards([]) // fallback 防止 UI 卡死
    }
  }

  const formatRewards = (poolId: string, rawData: any) => {
    const pool = vaultsFarmingObj?.[poolId]
    console.log('🚀🚀🚀 ~ useGetVaultFarmingAvailableRewards.ts:31 ~ formatRewards ~ pool:', pool)
    if (!pool || !pool.rewardConfigs) {
      console.warn(`[VaultFarming] Missing rewardConfigs for pool ${poolId}`)
      return []
    }

    return pool.rewardConfigs
      .filter((item: any) => d(item.rate).gt(0))
      .map((item: any) => {
        const rewardAmount = rawData?.[item.rewardCoinType] ?? '0'
        const rewardAmountDisplay = d(rewardAmount)
          .div(10 ** (item.coinDetail?.decimals ?? 0))
          .toString()

        return {
          ...item,
          rewardAmount,
          rewardAmountDisplay
        }
      })
  }

  return { getVaultFarmingAvailableRewards }
}
